// ============================================================
// Keystone PT Script  -  Generated by Keystone Automation
//
// HOW TO USE
//   1. Open Packet Tracer
//   2. Place ONE seed device on the canvas for each type below:
//        - One 2911  (router)
//        - One 2960  (switch)
//        - One Server-PT  (server)
//        - One PC-PT  (pc)
//   3. Extensions  ->  Scripting  ->  Edit File Script Module
//   4. Load this file and click  Run
//   5. Manually cable the connections shown in the console output
//   6. Delete the original seed device(s) from the canvas
//   7. File  ->  Save As  ->  your_lab.pkt
//
// Topology: 6 device(s), 0 connection(s)
// ============================================================

function main()
{
    dprint("=== KEYSTONE TOPOLOGY BUILDER ===");
    dprint("");

    try {

        var network    = ipc.network();
        var activeFile = ipc.appWindow().getActiveFile();

        dprint("Seed devices on canvas: " + network.getDeviceCount());

        // ===== PHASE 1: LOCATE SEED DEVICES =====
        dprint("[1/4] Locating seed devices...");
        var seeds = {};
        for (var i = 0; i < network.getDeviceCount(); i++) {
            var d     = network.getDeviceAt(i);
            var model = d.getModel();
            if (!seeds[model]) {
                seeds[model] = d;
                dprint("  OK  Found seed: " + model + " (" + d.getName() + ")");
            }
        }

        if (!seeds["2911"]) {
            dprint("  ERR  Missing seed: 2911");
            dprint("       Add one router (2911) to the canvas and re-run.");
            return;
        }
        if (!seeds["2960"]) {
            dprint("  ERR  Missing seed: 2960");
            dprint("       Add one switch (2960) to the canvas and re-run.");
            return;
        }
        if (!seeds["Server-PT"]) {
            dprint("  ERR  Missing seed: Server-PT");
            dprint("       Add one server (Server-PT) to the canvas and re-run.");
            return;
        }
        if (!seeds["PC-PT"]) {
            dprint("  ERR  Missing seed: PC-PT");
            dprint("       Add one pc (PC-PT) to the canvas and re-run.");
            return;
        }

        // ===== PHASE 2: CREATE DEVICES =====
        dprint("[2/4] Creating devices...");
        var devs = {};

        // --- OFFICE-ROUTER ---
        activeFile.duplicateDevice(seeds["2911"]);
        var dev_OFFICE_ROUTER = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_OFFICE_ROUTER.moveToLocationCentered(120, 120);
        devs["OFFICE-ROUTER"] = dev_OFFICE_ROUTER;
        dprint("  +  OFFICE-ROUTER at (120, 120)");
        java.lang.Thread.sleep(300);

        // --- OFFICE-SWITCH ---
        activeFile.duplicateDevice(seeds["2960"]);
        var dev_OFFICE_SWITCH = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_OFFICE_SWITCH.moveToLocationCentered(340, 120);
        devs["OFFICE-SWITCH"] = dev_OFFICE_SWITCH;
        dprint("  +  OFFICE-SWITCH at (340, 120)");
        java.lang.Thread.sleep(300);

        // --- PRINTER ---
        activeFile.duplicateDevice(seeds["Server-PT"]);
        var dev_PRINTER = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_PRINTER.moveToLocationCentered(560, 120);
        devs["PRINTER"] = dev_PRINTER;
        dprint("  +  PRINTER at (560, 120)");
        java.lang.Thread.sleep(300);

        // --- USER-PC-1 ---
        activeFile.duplicateDevice(seeds["PC-PT"]);
        var dev_USER_PC_1 = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_USER_PC_1.moveToLocationCentered(780, 120);
        devs["USER-PC-1"] = dev_USER_PC_1;
        dprint("  +  USER-PC-1 at (780, 120)");
        java.lang.Thread.sleep(300);

        // --- USER-PC-2 ---
        activeFile.duplicateDevice(seeds["PC-PT"]);
        var dev_USER_PC_2 = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_USER_PC_2.moveToLocationCentered(1000, 120);
        devs["USER-PC-2"] = dev_USER_PC_2;
        dprint("  +  USER-PC-2 at (1000, 120)");
        java.lang.Thread.sleep(300);

        // --- USER-PC-3 ---
        activeFile.duplicateDevice(seeds["PC-PT"]);
        var dev_USER_PC_3 = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_USER_PC_3.moveToLocationCentered(120, 340);
        devs["USER-PC-3"] = dev_USER_PC_3;
        dprint("  +  USER-PC-3 at (120, 340)");
        java.lang.Thread.sleep(300);

        // ===== PHASE 3: CONNECTIONS (manual cabling required) =====
        dprint("[3/4] Connections to cable manually:");
        dprint("  (no connections defined in topology)");

        // ===== PHASE 4: CONFIGURE DEVICES =====
        dprint("[4/4] Configuring devices (this may take a moment)...");

        dprint("  >> OFFICE-ROUTER");
        configureDevice(devs["OFFICE-ROUTER"], ["enable", "configure terminal", "hostname OFFICE-ROUTER", "interface GigabitEthernet0/0/0", " description Internet uplink", " ip address 203.0.113.50 255.255.255.0", " no shutdown", " exit", "interface GigabitEthernet0/0/1", " description Office LAN", " ip address 192.168.10.1 255.255.255.0", " no shutdown", " exit", "ip dhcp pool OFFICE", " network 192.168.10.0 255.255.255.0", " default-router 192.168.10.1", " dns-server 8.8.8.8", " exit", "ip dhcp excluded-address 192.168.10.1 192.168.10.10", "interface GigabitEthernet0/0/1", " ip nat inside", " exit", "interface GigabitEthernet0/0/0", " ip nat outside", " exit", "ip nat pool OFFICE-POOL 203.0.113.100 203.0.113.110 netmask 255.255.255.0", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> OFFICE-SWITCH");
        configureDevice(devs["OFFICE-SWITCH"], ["enable", "configure terminal", "hostname OFFICE-SWITCH", "interface GigabitEthernet0/1", " description Uplink to router", " no shutdown", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> PRINTER");
        configureDevice(devs["PRINTER"], ["enable", "configure terminal", "hostname PRINTER", "interface GigabitEthernet0/0/0", " description Network printer", " ip address 192.168.10.20 255.255.255.0", " no shutdown", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> USER-PC-1");
        configureDevice(devs["USER-PC-1"], ["enable", "configure terminal", "hostname USER-PC-1", "interface FastEthernet0", " description Employee workstation 1", " no shutdown", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> USER-PC-2");
        configureDevice(devs["USER-PC-2"], ["enable", "configure terminal", "hostname USER-PC-2", "interface FastEthernet0", " description Employee workstation 2", " no shutdown", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> USER-PC-3");
        configureDevice(devs["USER-PC-3"], ["enable", "configure terminal", "hostname USER-PC-3", "interface FastEthernet0", " description Employee workstation 3", " no shutdown", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("");
        dprint("=== TOPOLOGY COMPLETE ===");
        dprint("  Devices created : 6");
        dprint("  Connections     : 0 (see above for cabling)");
        dprint("");
        dprint("Next steps:");
        dprint("  1. Cable the connections listed above");
        dprint("  2. Delete the original seed device(s)");
        dprint("  3. File -> Save As -> your_lab.pkt");

    } catch(e) {
        dprint("FATAL ERROR: " + e.message);
        dprint(e.stack);
    }
}


// ============================================================
// Helper: send a list of IOS CLI commands to a device
// ============================================================
function configureDevice(device, commands)
{
    try {
        var cli = device.getCommandLine();
        if (cli == null) {
            dprint("  WARN  No CLI available for " + device.getName());
            return;
        }

        // Dismiss the initial configuration dialog if it appears
        var initialOut = cli.getOutput();
        if (initialOut.indexOf("initial configuration dialog") > -1) {
            cli.enterCommand("no");
            java.lang.Thread.sleep(500);
        }

        // Send each command with a short delay
        for (var i = 0; i < commands.length; i++) {
            cli.enterCommand(commands[i]);
            java.lang.Thread.sleep(100);
        }

        dprint("  OK  " + device.getName());

    } catch(e) {
        dprint("  ERR  " + device.getName() + ": " + e.message);
    }
}


function cleanUp()
{
    dprint("Script cleanup complete.");
}
